/**
 * SUMMARY.md (§16): generated by @hogee/verify-evidence's summaryMarkdown, which the verifier also runs on the
 * bundle's files and compares byte for byte (run-6 v-6). This adapter maps the exporter's inputs onto it.
 */
import type { BundleManifest, EvidenceRow } from "@hogee/core";
import { summaryMarkdown as bundleSummary, type ContractsFile } from "@hogee/verify-evidence";
import type { Collected } from "./collect";

export interface SummaryInput {
  readonly manifest: BundleManifest;
  readonly contracts: ContractsFile;
  readonly rows: readonly EvidenceRow[];
  readonly collected: Collected;
  readonly receipts: number;
  readonly countryPackIncluded: boolean;
}

export function summaryMarkdown(s: SummaryInput): string {
  const c = s.collected;
  return bundleSummary({
    manifest: s.manifest,
    contracts: s.contracts,
    rows: s.rows,
    payments: c.payments,
    chainActions: c.chainActions,
    counts: { plans: c.plans.length, signatures: c.signatures.length, traces: c.traces.length, llmCalls: c.llmCalls.length, rationales: c.rationales.length, receipts: s.receipts },
    countryPackIncluded: s.countryPackIncluded,
  });
}
